from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "reference"))
from enigma_ref import ROTORS, ROTOR_ORDER, REFLECTOR_B

def generate():
    out = ROOT / "fpga" / "rtl"
    out.mkdir(parents=True, exist_ok=True)
    lines = [
        "// Generated by tools/gen_fpga_files.py; one 32-bit truth table per output bit.",
        "module rotor_rom (input [2:0] rotor, input inv,",
        "  input [4:0] x, output reg [4:0] y);",
    ]
    tables = []
    for rid, name in enumerate(ROTOR_ORDER):
        forward = [ord(c) - 65 for c in ROTORS[name][0]]
        inverse = [0] * 26
        for i, value in enumerate(forward):
            inverse[value] = i
        for direction, table in enumerate((forward, inverse)):
            tables.append(((rid << 1) | direction, table))
    tables.append((10, [ord(c) - 65 for c in REFLECTOR_B]))
    for key, table in tables:
        lines.append(f"wire [4:0] table_{key};")
        for bit in range(5):
            mask = sum(((v >> bit) & 1) << i for i, v in enumerate(table))
            lines.append(f"localparam [31:0] MASK_{key}_{bit} = 32'h{mask:08x};")
            lines.append(f"assign table_{key}[{bit}] = MASK_{key}_{bit}[x];")
    lines += ["always @(*) begin", "  case ({rotor, inv})"]
    for key, table in tables:
        lines.append(f"    4'd{key}: y = table_{key};")
    lines += ["    default: y = 5'd0;", "  endcase", "end", "endmodule"]
    target = out / "rotor_rom.v"
    target.write_text("\n".join(lines) + "\n", encoding="ascii")
    print(target.relative_to(ROOT))

if __name__ == "__main__":
    generate()
